const logger = winston.createLogger({
  level: 'error',
  format: winston.format.json(),
  transports: [new winston.transports.File({ filename: 'error.log' })],
});

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

const app = express();

// Middleware
app.use(helmet());
app.use(
  csp({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", 'trusted.cdn.com'],
    },
  })
);
app.use(cors({ origin: ['https://your-trusted-domain.com'] }));
app.use(express.json());
app.use(morgan('combined'));
app.use(nocache()); // Disable caching for sensitive routes

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// Routes
app.get(
  '/health',
  query('timestamp').optional().isISO8601(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  }
);

app.get(
  '/users',
  query('id').optional().isInt().withMessage('ID must be an integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    try {
      const users = [
        { id: 1, name: xss('Alice'), email: xss('alice@example.com') },
        { id: 2, name: xss('Bob'), email: xss('bob@example.com') },
      ];
      res.json(users);
    } catch (err) {
      logger.error(err.stack);
      if (err.isOperational) {
        res.status(err.statusCode).json({ error: err.message });
      } else {
        res.status(500).json({ error: 'Internal Server Error' });
      }
    }
  }
);

// Error Handling
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  logger.error(err.stack);
  res.status(err.statusCode || 500).json({
    error: err.isOperational ? err.message : 'Internal Server Error',
  });
});

// Start Server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

module.exports = app;

